#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

#define MAX_GROUPS 32

typedef struct {
    int left, right;
    int offset, capacity;
    int length, total_gcd;
    int prefix_count, suffix_count;
    long long answer;
} Node;

typedef struct {
    int length, total_gcd;
    int prefix_count, suffix_count;
    long long answer;
    int prefix_gcd[MAX_GROUPS], prefix_cum[MAX_GROUPS];
    int suffix_gcd[MAX_GROUPS], suffix_cum[MAX_GROUPS];
} Summary;

static Node *tree;
static int *pool;
static int node_count, pool_capacity;
static int n;
static int values[100005];

static int gcd_int(int a, int b) {
    while (b) {
        int t = a % b;
        a = b;
        b = t;
    }
    return a;
}

static int create_tree(int left, int right) {
    int id = node_count++;
    Node *node = &tree[id];

    node->length = right - left + 1;
    node->capacity = node->length < MAX_GROUPS ? node->length : MAX_GROUPS;
    node->offset = pool_capacity;
    pool_capacity += node->capacity;

    if (left == right) {
        node->left = node->right = -1;
    } else {
        int mid = (left + right) / 2;
        node->left = create_tree(left, mid);
        node->right = create_tree(mid + 1, right);
    }
    return id;
}

static void load_summary(int id, Summary *s) {
    Node *node = &tree[id];
    int cap = node->capacity;
    int off = node->offset;

    s->length = node->length;
    s->total_gcd = node->total_gcd;
    s->prefix_count = node->prefix_count;
    s->suffix_count = node->suffix_count;
    s->answer = node->answer;

    for (int i = 0; i < s->prefix_count; ++i) {
        s->prefix_gcd[i] = pool[off + i];
        s->prefix_cum[i] = pool[off + cap + i];
    }
    for (int i = 0; i < s->suffix_count; ++i) {
        s->suffix_gcd[i] = pool[off + 2 * cap + i];
        s->suffix_cum[i] = pool[off + 3 * cap + i];
    }
}

static void store_summary(int id, const Summary *s) {
    Node *node = &tree[id];
    int cap = node->capacity;
    int off = node->offset;

    node->total_gcd = s->total_gcd;
    node->prefix_count = s->prefix_count;
    node->suffix_count = s->suffix_count;
    node->answer = s->answer;

    for (int i = 0; i < s->prefix_count; ++i) {
        pool[off + i] = s->prefix_gcd[i];
        pool[off + cap + i] = s->prefix_cum[i];
    }
    for (int i = 0; i < s->suffix_count; ++i) {
        pool[off + 2 * cap + i] = s->suffix_gcd[i];
        pool[off + 3 * cap + i] = s->suffix_cum[i];
    }
}

static void append_group(int *gcds, int *cumulative, int *count,
                         int gcd_value, int amount) {
    if (*count > 0 && gcds[*count - 1] == gcd_value) {
        cumulative[*count - 1] += amount;
    } else {
        int previous = *count ? cumulative[*count - 1] : 0;
        gcds[*count] = gcd_value;
        cumulative[*count] = previous + amount;
        ++(*count);
    }
}

static void merge_summaries(const Summary *a, const Summary *b, Summary *out) {
    out->length = a->length + b->length;
    out->total_gcd = gcd_int(a->total_gcd, b->total_gcd);
    out->answer = a->answer + b->answer;

    out->prefix_count = 0;
    for (int i = 0; i < a->prefix_count; ++i) {
        int amount = a->prefix_cum[i] - (i ? a->prefix_cum[i - 1] : 0);
        append_group(out->prefix_gcd, out->prefix_cum,
                     &out->prefix_count, a->prefix_gcd[i], amount);
    }
    for (int i = 0; i < b->prefix_count; ++i) {
        int amount = b->prefix_cum[i] - (i ? b->prefix_cum[i - 1] : 0);
        int g = gcd_int(a->total_gcd, b->prefix_gcd[i]);
        append_group(out->prefix_gcd, out->prefix_cum,
                     &out->prefix_count, g, amount);
    }

    out->suffix_count = 0;
    for (int i = 0; i < b->suffix_count; ++i) {
        int amount = b->suffix_cum[i] - (i ? b->suffix_cum[i - 1] : 0);
        append_group(out->suffix_gcd, out->suffix_cum,
                     &out->suffix_count, b->suffix_gcd[i], amount);
    }
    for (int i = 0; i < a->suffix_count; ++i) {
        int amount = a->suffix_cum[i] - (i ? a->suffix_cum[i - 1] : 0);
        int g = gcd_int(b->total_gcd, a->suffix_gcd[i]);
        append_group(out->suffix_gcd, out->suffix_cum,
                     &out->suffix_count, g, amount);
    }

    long long crossing = 0;
    int j = b->prefix_count - 1;
    for (int i = 0; i < a->suffix_count; ++i) {
        while (j >= 0 && gcd_int(a->suffix_gcd[i], b->prefix_gcd[j]) == 1)
            --j;

        if (j >= 0) {
            int amount = a->suffix_cum[i] - (i ? a->suffix_cum[i - 1] : 0);
            crossing += (long long)amount * b->prefix_cum[j];
        }
    }
    out->answer += crossing;
}

static void build_values(int id, int left, int right) {
    if (left == right) {
        Summary s = {0};
        int value = values[left];
        s.length = 1;
        s.total_gcd = value;
        s.answer = value > 1;
        s.prefix_count = s.suffix_count = 1;
        s.prefix_gcd[0] = s.suffix_gcd[0] = value;
        s.prefix_cum[0] = s.suffix_cum[0] = 1;
        store_summary(id, &s);
        return;
    }

    int mid = (left + right) / 2;
    build_values(tree[id].left, left, mid);
    build_values(tree[id].right, mid + 1, right);

    Summary a, b, result;
    load_summary(tree[id].left, &a);
    load_summary(tree[id].right, &b);
    merge_summaries(&a, &b, &result);
    store_summary(id, &result);
}

static void update_value(int id, int left, int right, int position, int value) {
    if (left == right) {
        Summary s = {0};
        s.length = 1;
        s.total_gcd = value;
        s.answer = value > 1;
        s.prefix_count = s.suffix_count = 1;
        s.prefix_gcd[0] = s.suffix_gcd[0] = value;
        s.prefix_cum[0] = s.suffix_cum[0] = 1;
        store_summary(id, &s);
        return;
    }

    int mid = (left + right) / 2;
    if (position <= mid)
        update_value(tree[id].left, left, mid, position, value);
    else
        update_value(tree[id].right, mid + 1, right, position, value);

    Summary a, b, result;
    load_summary(tree[id].left, &a);
    load_summary(tree[id].right, &b);
    merge_summaries(&a, &b, &result);
    store_summary(id, &result);
}

static void query_range(int id, int left, int right, int ql, int qr,
                        Summary *result) {
    if (ql <= left && right <= qr) {
        load_summary(id, result);
        return;
    }

    int mid = (left + right) / 2;
    if (qr <= mid) {
        query_range(tree[id].left, left, mid, ql, qr, result);
    } else if (ql > mid) {
        query_range(tree[id].right, mid + 1, right, ql, qr, result);
    } else {
        Summary a, b;
        query_range(tree[id].left, left, mid, ql, qr, &a);
        query_range(tree[id].right, mid + 1, right, ql, qr, &b);
        merge_summaries(&a, &b, result);
    }
}

static int read_int(void) {
    int c = getchar();
    while (c <= ' ' && c != EOF) c = getchar();

    int value = 0;
    while (c > ' ') {
        value = value * 10 + (c - '0');
        c = getchar();
    }
    return value;
}

int main(void) {
    n = read_int();
    int m = read_int();

    for (int i = 1; i <= n; ++i)
        values[i] = read_int();

    tree = (Node *)malloc((size_t)(2 * n) * sizeof(Node));
    int root = create_tree(1, n);
    pool = (int *)malloc((size_t)pool_capacity * 4 * sizeof(int));

    build_values(root, 1, n);

    while (m--) {
        int type = read_int();
        int x = read_int();
        int y = read_int();

        if (type == 1) {
            update_value(root, 1, n, x, y);
        } else {
            Summary result;
            query_range(root, 1, n, x, y, &result);
            printf("%lld\n", result.answer);
        }
    }

    free(pool);
    free(tree);
    return 0;
}
